#!/usr/bin/env bash
# land-the-wider-net-and-the-shorter-list.sh  ·  run from the REPO ROOT
#   bash land-the-wider-net-and-the-shorter-list.sh && git push
#
# Owner, 17 Aug, after "Jobs from the web" landed: add Adzuna and Jooble too,
# and "just show the user relevant jobs only based on the CV". Two halves,
# named in the title.
#
# THE WIDER NET. Adzuna and Jooble are licensed aggregator APIs with free
# tiers — they index boards the three ATS vendors don't host, and reading
# them is what their API exists for (unlike Naukri/LinkedIn scraping, which
# stays refused). Both are OPTIONAL and keyed by the owner:
#
#     ADZUNA_APP_ID / ADZUNA_APP_KEY   ← developer.adzuna.com  (free)
#     JOOBLE_API_KEY                   ← jooble.org/api/about  (free, by request)
#
# Set them in Railway and the next sweep starts asking; leave them empty and
# those sources are skipped with one log line each ("adzuna: no
# ADZUNA_APP_ID/ADZUNA_APP_KEY - skipped") — a silently absent source looks
# identical to a broken one, so it says so. The sweep asks a rotating 6 of 22
# industry queries per run (engineer to nurse to accountant — the same
# breadth the skill dictionary parses), ≈24 calls/day per aggregator, far
# under the free tiers. India-scoped BY CONSTRUCTION — Adzuna's /jobs/in/
# path, Jooble's location field — so a posting in Salem or Guwahati counts
# without the city list having heard of the town. Aggregator rows unseen for
# 14 days are deleted (a board re-read proves closure; an aggregator only
# stops answering, so staleness is the honest proxy). Adzuna's STATED
# salaries land as ₹ LPA on the card; its PREDICTED ones are refused at
# ingest, and Jooble's free-text salary strings are not parsed at all — a
# "₹40,000/month" misread as 40 LPA is worse than silence.
#
# THE SHORTER LIST. matches() now serves ONLY the shortlist, decided by a
# pure rule in jobs-engine (relevantMatches, spec-covered): no 'weak' fits
# anywhere, an EXTERNAL role must share at least one skill with the CV (its
# score can clear 'weak' on seniority alone, and a page of plausible scores
# with zero matched skills is the feed inventing relevance), capped at 80.
# City postings are exempt from the shared-skill cut — the board is
# employer-curated and small. The page's "other open roles - a weaker fit"
# tail is gone; what arrives is what fits.
#
# SCHEMA: one additive column (ExternalJob.salaryLpa, default 0 = "the
# source did not say") — migration 20260817040000_the_wider_net.
#
# VERIFIED IN THE SANDBOX: pure layer tsc; the external spec grown 12 → 18
# (aggregator normalizers, salary refusals, the shortlist rule); engine
# audit still green; web tsc; full web suite 890/890; ceilings; build. NOT
# verifiable there, same as last time: prisma generate (engine 403s) so API
# tsc + full jest gate here first, and live aggregator calls (sandbox
# egress) — shapes are fixture-proven against both vendors' documented
# responses; the first keyed sweep on Railway is the live proof, logs:
#   ExternalJobs: adzuna: 6 queries from #0 - N postings, 0 queries failed
#
# PRECONDITION: land-jobs-from-the-web.sh has landed.
set -uo pipefail
W=together-city-react
A=together-city-chat

say(){ printf '\n\033[1m%s\033[0m\n' "$*"; }
ok(){  printf '   \033[32m*\033[0m %s\n' "$*"; }
note(){ printf '   \033[33m~\033[0m %s\n' "$*"; }
die(){ printf '   \033[31mx\033[0m %s\n' "$*"; exit 1; }

[ -d "$W" ] && [ -d "$A" ] || die "run me from the repo root"

say "1 - preconditions"
if [ -f .git/index.lock ] && [ ! -s .git/index.lock ]; then rm -f .git/index.lock && ok "cleared an empty index.lock"; fi
git log --oneline -40 | grep 'Jobs from the web' >/dev/null \
  || die "land-jobs-from-the-web.sh has not landed - this script names it as its precondition"
git log --oneline -40 | grep 'The wider net and the shorter list' >/dev/null \
  && die "already landed - re-running is a no-op by design"
git diff --quiet -- "$A/prisma/schema.prisma" "$A/.env.example" "$A/src/jobs" "$W/src/features/jobs" "$W/src/app/jobs-from-the-web.test.ts" \
  || die "uncommitted changes on this change's own files - stash them first"
ok "clean where it matters, and not landed yet"
STRAY="$(git status --porcelain -uno | grep -v '^[[:space:]]*$' || true)"
if [ -n "$STRAY" ]; then
  note "other files are dirty and are NOT part of this commit:"
  printf '%s\n' "$STRAY" | sed 's/^/       /'
  note "if a gate below fails inside one of those files, stash them and re-run:"
  note "  git stash push -u -m wip -- $W/src $A/src   ...then land, push, git stash pop"
fi

say "2 - decode the patch, prove it is the patch, prove it applies"
PATCH="$(mktemp)"
openssl base64 -d -A > "$PATCH" <<'B64EOF'

B64EOF
[ -s "$PATCH" ] || die "the decode produced an empty file"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
WANT="e4acfd04ae39dd50b2ab876a931f1b026e1db1713d52c2290934f7b78157f36e"
[ "$GOT" = "$WANT" ] || die "sha256 mismatch: got $GOT"
ok "sha256 verified"
git apply --check -C1 "$PATCH" || die "patch does not apply - the tree has moved since this was written"
git apply -C1 "$PATCH" || die "apply"
ok "applied - 10 files, 1 new migration"

say "3 - the API gates"
cd "$A"
npx prisma generate || die "prisma generate - a new column needs it before anything typechecks"
ok "prisma client regenerated"
npx tsc --noEmit || die "api tsc"
ok "api tsc clean"
npx jest src/jobs || die "the jobs suites - engine audit, cv entries, and the grown external spec"
ok "jobs suites green (external spec now 18 tests)"
EXPECTED_RED="src/dev/dev.spec.ts src/security/query-scoping.spec.ts src/security/route-reach.spec.ts src/security/runtime-isolation.spec.ts src/shared/swallow.spec.ts src/shared/unbounded-reads.spec.ts src/shared/voice-scan.spec.ts "
OUT="$(npx jest 2>&1 || true)"
RED="$(printf '%s\n' "$OUT" | grep -E '^[[:space:]]*FAIL ' | awk '{print $2}' | sort -u | tr '\n' ' ')"
if [ "$RED" != "$EXPECTED_RED" ]; then
  printf '%s\n' "$OUT" | tail -60
  printf '\n   expected red: %s\n   actually red: %s\n' "$EXPECTED_RED" "$RED"
  die "the API suite's failing set changed - this commit is answerable for the difference"
fi
note "7 suites red on main, and still exactly those 7"
cd ..

say "4 - the web gates"
cd "$W"
npx tsc --noEmit || die "web tsc"
ok "web tsc clean"
npx vitest run src/app/jobs-from-the-web.test.ts || die "the jobs guard (now 5 tests)"
npx vitest run || die "web suite"
ok "web suite green (890 at time of writing)"
node scripts/lint-ceiling.mjs   || die "lint ceiling"
node scripts/nav-audit.mjs      || die "nav audit"
node scripts/a11y-audit.mjs     || die "a11y ceiling"
node scripts/motion-ceiling.mjs || die "motion ceiling"
DEAD="$(node scripts/dead-export-audit.mjs --list 2>&1 | grep -E '^\s+features/' | awk '{print $2}' | sort | tr '\n' ' ')"
[ "$DEAD" = "MedicalAdvisories PlanGuidanceBanner useGemCommission " ] \
  || die "dead exports changed: $DEAD (expected the pre-existing three)"
ok "lint, nav, a11y, motion, dead-export all at ceiling"
npm run build >/dev/null 2>&1 || die "vite build"
ok "vite build clean"
cd ..

say "5 - commit"
git add "$A/.env.example" \
        "$A/prisma/schema.prisma" \
        "$A/prisma/migrations/20260817040000_the_wider_net/migration.sql" \
        "$A/src/jobs/jobs-engine.ts" \
        "$A/src/jobs/jobs.service.ts" \
        "$A/src/jobs/external/ats.ts" \
        "$A/src/jobs/external/external-jobs.service.ts" \
        "$A/src/jobs/external/external-ats.spec.ts" \
        "$W/src/features/jobs/pages/Matches.tsx" \
        "$W/src/app/jobs-from-the-web.test.ts" \
        land-the-wider-net-and-the-shorter-list.sh
git commit -m "The wider net and the shorter list" -m \
"Owner, after Jobs from the web landed: add Adzuna and Jooble too, and show
the user relevant jobs only, based on the CV.

The wider net: Adzuna and Jooble are licensed aggregator APIs with free
tiers, optional and keyed by the owner (ADZUNA_APP_ID/ADZUNA_APP_KEY,
JOOBLE_API_KEY - .env.example documents both; empty keys skip the source
with one log line, because a silently absent source looks identical to a
broken one). The sweep asks a rotating 6 of 22 industry queries per run -
engineer to nurse to accountant, the same breadth the skill dictionary
parses - about 24 calls a day per aggregator. India-scoped by construction
(Adzuna's /jobs/in/ path, Jooble's location field), so a posting in Salem
counts without the city list having heard of the town. Aggregator rows
unseen 14 days are deleted: a board re-read proves closure, an aggregator
only stops answering. Adzuna's stated salaries land as LPA on the card; its
predicted ones are refused at ingest, and Jooble's free-text salary strings
are not parsed - a 40,000-per-month misread as 40 LPA is worse than silence.

The shorter list: matches() serves only the shortlist, decided by a pure
spec-covered rule (jobs-engine.relevantMatches). No weak fits anywhere; an
external role must share at least one skill with the CV, because its score
can clear weak on seniority alone and a page of plausible scores with zero
matched skills is the feed inventing relevance; capped at 80. City postings
are exempt from the shared-skill cut - the board is employer-curated and
small. The page's weaker-fit tail is gone; what arrives is what fits.

One additive column: ExternalJob.salaryLpa, 0 = the source did not say,
which the card renders as silence, never as Rs 0." \
  || die "commit"
ok "committed"
git log --oneline -1

say "done - now: git push"
say "NOTE: a migration (20260817040000_the_wider_net) - Railway applies it on deploy."
say "THEN set the keys in Railway to switch the aggregators on:"
say "  ADZUNA_APP_ID / ADZUNA_APP_KEY   from developer.adzuna.com (free)"
say "  JOOBLE_API_KEY                   from jooble.org/api/about (free)"
say "Without them the ATS sweep keeps running exactly as before."
